class SimpleMLP(nn.Module):
    def __init__(self):
        super().__init__()
        self.proj_in = nn.Linear(12, 128)
        self.layers = nn.ModuleList([
            nn.Sequential(
                nn.Linear(128, 128),
                nn.LayerNorm(128),
                nn.GELU(),
            )
        ])
        self.proj_out = nn.Linear(128, 1)

    def forward(self, x):
        x = F.gelu(self.proj_in(x))
        for layer in self.layers:
            x1 = layer(x)
            x = x + x1
        x = self.proj_out(x)
        return x
